  publications: "<section class=\"inz-section\" style=\"background: linear-gradient(135deg, #1b1464 0%, #16307f 60%, #097bb8 100%); color: #ffffff; padding: clamp(4rem, 10vw, 6rem) 0; text-align: center;\">\n  <div class=\"inz-container\">\n    <h1 style=\"color: #ffffff; max-width: 18ch; margin-inline: auto;\">Publications</h1>\n    <p style=\"color: #e8e6ee; max-width: 55ch; margin: 0 auto;\">Reports, India Report editions and research published by INZBC.</p>\n  </div>\n</section>\n\n<section class=\"inz-section\" style=\"background-color: #ffffff; padding: clamp(3rem, 6vw, 4.5rem) 0;\">\n  <div class=\"inz-container\">\n    <h2>India Report</h2>\n    <p>[[Confirm which India Report editions carry over. The April 2023 edition is referenced in the trade page.]]</p>\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(18rem, 1fr)); gap: 1.5rem; margin-top: 2rem;\">\n      <div style=\"padding: 1.5rem; background: #f6f5f8; border-radius: 10px;\">\n        <h3 style=\"font-size: 1.35rem;\">India Report 2.0</h3>\n        <p style=\"margin: 0 0 1rem;\">[[Description / date]]</p>\n        <a href=\"#\" class=\"inz-btn inz-btn--primary\" style=\"padding: 0.6em 1.2em; font-size: 0.875rem;\">Read HTML</a>\n        <a href=\"#\" class=\"inz-btn inz-btn--secondary\" style=\"padding: 0.6em 1.2em; font-size: 0.875rem;\">Download PDF</a>\n      </div>\n    </div>\n  </div>\n</section>",
  newsletters: "<section class=\"inz-section\" style=\"background: linear-gradient(135deg, #1b1464 0%, #16307f 60%, #097bb8 100%); color: #ffffff; padding: clamp(4rem, 10vw, 6rem) 0; text-align: center;\">\n  <div class=\"inz-container\">\n    <h1 style=\"color: #ffffff; max-width: 18ch; margin-inline: auto;\">Newsletters</h1>\n    <p style=\"color: #e8e6ee; max-width: 55ch; margin: 0 auto;\">Kia Ora India, the monthly newsletter archive, and the Trade Intelligence Digest.</p>\n  </div>\n</section>\n\n<section class=\"inz-section\" style=\"background-color: #ffffff; padding: clamp(3rem, 6vw, 4.5rem) 0;\">\n  <div class=\"inz-container\">\n    <h2>Kia Ora India</h2>\n    <p>[[The site currently describes Kia Ora India as quarterly with a December 2023 \"latest\" issue. Confirm current cadence and latest issue with INZBC before publish.]]</p>\n\n    <h2 style=\"margin-top: 2.5rem;\">Trade Intelligence Digest</h2>\n    <p>Weekly, LLM-summarised, human-reviewed digest of India–NZ trade news. Renders only items with CMS status = published.</p>\n    <a href=\"#\" class=\"inz-btn inz-btn--primary\" style=\"margin-top: 1rem;\">Browse the archive</a>\n\n    <h2 style=\"margin-top: 2.5rem;\">Monthly newsletter archive</h2>\n    <p>[[Confirm Mailchimp vs eocampaign hosting. Link to archive.]]</p>\n  </div>\n</section>",
